{
  "name": "llm_adv_pdu_build",
  "confidence": "medium",
  "docstring": "Applies an advertising PDU descriptor to the BLE link-layer context, lazily loading the advertising PDU type table and programming the control word, addresses, and descriptor submit flag.",
  "subsystem": "ble",
  "var_renames": {
    "v1": "adv_desc_ptrs",
    "v2": "adv_pdu_type_entry",
    "v3": "adv_pdu_ctrl_word",
    "v4": "adv_pdu_type_table",
    "v5": "cleared_ctrl_word",
    "v6": "adv_desc_flags"
  },
  "struct_hints": [
    {
      "offset": 28,
      "meaning": "command/message field containing a pointer pair to the advertising PDU descriptor and link-layer context"
    },
    {
      "offset": 20,
      "meaning": "link-layer context field pointing to the loaded advertising PDU type table"
    },
    {
      "offset": 24,
      "meaning": "link-layer context cached advertising PDU type entry pointer"
    },
    {
      "offset": 60,
      "meaning": "link-layer advertising control word; bits 9 and 10 are cleared, then bit 9 is set based on the PDU type entry flag"
    },
    {
      "offset": 44,
      "meaning": "advertising PDU descriptor transmit address or pointer copied to link-layer context offset 44"
    },
    {
      "offset": 40,
      "meaning": "link-layer context field receiving the descriptor auxiliary address at offset 100"
    },
    {
      "offset": 48,
      "meaning": "advertising PDU descriptor flags; bit 2 marks the descriptor submitted or valid"
    },
    {
      "offset": 96,
      "meaning": "advertising PDU descriptor control word copied to link-layer context offset 60"
    },
    {
      "offset": 100,
      "meaning": "advertising PDU descriptor auxiliary address or parameter copied to link-layer context offset 40"
    },
    {
      "offset": 8,
      "meaning": "offset inside advertising PDU type table entry pointing to the per-type flag/control structure"
    },
    {
      "offset": 4,
      "meaning": "per-type flag byte bit 0 controls whether link-layer control bit 9 is set"
    }
  ]
}
